// Reads the pdf.js worker and emits it as a base64 string module so it can be
// bundled into main.js and loaded via a Blob URL at runtime. This avoids
// shipping a separate worker file and the path/CORS issues that come with it.
import { readFileSync, writeFileSync } from "fs";

const WORKER_PATH = "node_modules/pdfjs-dist/legacy/build/pdf.worker.min.mjs";
const OUT_PATH = "src/pdf-worker-inline.ts";

const source = readFileSync(WORKER_PATH);
const base64 = source.toString("base64");

const out =
	"// AUTO-GENERATED by scripts/inline-pdf-worker.mjs — do not edit by hand.\n" +
	"// Contains the pdf.js worker, base64-encoded, to be loaded via a Blob URL.\n" +
	`export const PDF_WORKER_BASE64 = "${base64}";\n`;

writeFileSync(OUT_PATH, out);
console.log(`Inlined pdf worker (${(base64.length / 1024).toFixed(0)} KB base64) -> ${OUT_PATH}`);
